// ---------- helpers ----------
function hhmmToDecimal(v) {
  if (!v || v === "-" || v.trim() === "") return 0;
  const m = v.trim().match(/^(\d{1,3}):(\d{2})$/);
  if (!m) {
    const n = parseFloat(v.replace(",", "."));
    return isNaN(n) ? 0 : n;
  }
  return parseInt(m[1], 10) + parseInt(m[2], 10) / 60;
}
function decimalToHHMM(dec) {
  if (!dec) return "-";
  const h = Math.floor(dec);
  const m = Math.round((dec - h) * 60);
  return `${h}:${String(m).padStart(2, "0")}`;
}
function brl(v) {
  return (v || 0).toLocaleString("pt-BR", { style: "currency", currency: "BRL" });
}

// =========================================================
// CLASSIFICAÇÃO AUTOMÁTICA DE PONTO DIÁRIO
// Regras Prosign:
//  - Segunda: 08:30–17:30, almoço 12:00–13:00 (8h normais)
//  - Terça a sexta: 08:00–18:00, almoço 12:00–13:00 (9h normais)
//  - Sábado: sem expediente normal, tudo é extra 60%
//    (pode ter almoço manual descontado — ver almocoManualHoras)
//  - Domingo ou feriado (marcado manualmente): tudo é extra 100%
//    (pode ter almoço manual descontado — ver almocoManualHoras)
//  - 22:00–05:00: adicional noturno de 20% (sobre hora normal ou extra)
// =========================================================
const HORARIOS_SEMANA = {
  1: { inicio: "08:30", fim: "17:30" }, // segunda
  2: { inicio: "08:00", fim: "18:00" }, // terça
  3: { inicio: "08:00", fim: "18:00" }, // quarta
  4: { inicio: "08:00", fim: "18:00" }, // quinta
  5: { inicio: "08:00", fim: "18:00" }, // sexta
};
const ALMOCO = { inicio: "12:00", fim: "13:00" };
const NOITE_INICIO = "22:00";
const NOITE_FIM = "05:00";

function toMin(hhmm) {
  const [h, m] = hhmm.split(":").map(Number);
  return h * 60 + m;
}

function diaVazio() {
  return { he50: 0, he60: 0, he100: 0, heNot50: 0, heNot60: 0, heNot100: 0, adicNot: 0, normal: 0 };
}

// Classifica UM período de trabalho (entrada/saída) dentro do dia.
// Usado internamente por classificarDia para cada turno.
function classificarPeriodo(entradaStr, saidaStr, dataISO, feriado) {
  if (!entradaStr || !saidaStr || !dataISO) return diaVazio();
  const weekday = new Date(dataISO + "T00:00:00").getDay();

  let entrada = toMin(entradaStr);
  let saida = toMin(saidaStr);
  if (saida <= entrada) saida += 24 * 60;

  let horario = null;
  let percentual;
  if (feriado || weekday === 0) {
    percentual = "he100";
  } else if (weekday === 6) {
    percentual = "he60";
  } else {
    const h = HORARIOS_SEMANA[weekday];
    horario = { inicio: toMin(h.inicio), fim: toMin(h.fim) };
    percentual = "he50";
  }

  const almocoIni = toMin(ALMOCO.inicio);
  const almocoFim = toMin(ALMOCO.fim);
  const noiteIni = toMin(NOITE_INICIO);
  const noiteFim = toMin(NOITE_FIM);

  const NOT_MAP = { he50: "heNot50", he60: "heNot60", he100: "heNot100" };
  const buckets = diaVazio();

  for (let m = entrada; m < saida; m++) {
    const mod = m % 1440;
    if (horario && mod >= almocoIni && mod < almocoFim) continue;
    const noite = mod >= noiteIni || mod < noiteFim;
    const dentroHorario = horario && mod >= horario.inicio && mod < horario.fim;
    if (dentroHorario) {
      buckets.normal += 1;
      if (noite) buckets.adicNot += 1;
    } else {
      buckets[noite ? NOT_MAP[percentual] : percentual] += 1;
    }
  }
  Object.keys(buckets).forEach((k) => (buckets[k] = buckets[k] / 60));
  return buckets;
}

function somarBuckets(a, b) {
  const out = diaVazio();
  Object.keys(out).forEach((k) => (out[k] = (a[k] || 0) + (b[k] || 0)));
  return out;
}

function minToHHMM(min) {
  const m = ((min % 1440) + 1440) % 1440;
  const hh = Math.floor(m / 60);
  const mm = m % 60;
  return `${String(hh).padStart(2, "0")}:${String(mm).padStart(2, "0")}`;
}

// Classifica o dia inteiro, somando até 3 turnos de trabalho (ex.: turno
// normal + volta à noite para uma nova hora extra depois de ir pra casa).
// almocoHoras: usado em dias SEM horário fixo (sábado/domingo/feriado)
// quando foi dado um intervalo de almoço que precisa ser descontado das
// horas do 1º turno. Em dias com horário fixo, o almoço já é descontado
// automaticamente (ALMOCO.inicio–ALMOCO.fim) por turno.
//
// IMPORTANTE: o desconto do almoço manual é sempre feito no trecho DIURNO
// do turno (antes das 22h), nunca no trecho noturno — mesmo quando o
// horário de saída informado já passa das 22h. Isso evita "comer" minutos
// que já viraram adicional noturno (bug corrigido: um domingo 05:00–22:30
// com 1h de almoço deve virar 16:00 diurno + 0:30 noturno, e não 16:30
// diurno com o noturno zerado).
function classificarDia(registro) {
  const { entrada, saida, entrada2, saida2, entrada3, saida3, data, feriado, almocoHoras } = registro;
  const temHorarioFixo = diaTemHorarioFixo(data, feriado);

  let buckets;
  if (!temHorarioFixo && almocoHoras > 0 && entrada && saida) {
    let e = toMin(entrada);
    let s = toMin(saida);
    if (s <= e) s += 24 * 60;

    // Próxima ocorrência das 22h a partir da entrada.
    let noiteIniAbs = toMin(NOITE_INICIO);
    while (noiteIniAbs <= e) noiteIniAbs += 24 * 60;

    const almocoMin = Math.round(almocoHoras * 60);

    if (s > noiteIniAbs) {
      // O turno cruza as 22h: desconta o almoço só do trecho diurno,
      // mantendo o trecho noturno (das 22h em diante) intacto.
      let fimDiurnoAjustado = noiteIniAbs - almocoMin;
      if (fimDiurnoAjustado < e) fimDiurnoAjustado = e;
      buckets = classificarPeriodo(minToHHMM(e), minToHHMM(fimDiurnoAjustado), data, feriado);
      buckets = somarBuckets(buckets, classificarPeriodo(minToHHMM(noiteIniAbs), minToHHMM(s), data, feriado));
    } else {
      // Turno não alcança as 22h: desconta normalmente do fim.
      let sAjustada = s - almocoMin;
      if (sAjustada <= e) sAjustada = e;
      buckets = classificarPeriodo(entrada, minToHHMM(sAjustada), data, feriado);
    }
  } else {
    buckets = classificarPeriodo(entrada, saida, data, feriado);
  }

  if (entrada2 && saida2) buckets = somarBuckets(buckets, classificarPeriodo(entrada2, saida2, data, feriado));
  if (entrada3 && saida3) buckets = somarBuckets(buckets, classificarPeriodo(entrada3, saida3, data, feriado));
  return buckets;
}

function agregarMes(registros) {
  const soma = diaVazio();
  registros.forEach((r) => {
    const c = classificarDia(r);
    Object.keys(soma).forEach((k) => (soma[k] += c[k]));
  });
  return soma;
}

function mesRange(mesRef) {
  const [ano, mes] = mesRef.split("-").map(Number);
  const inicio = `${mesRef}-01`;
  const fimExclusivo = mes === 12 ? `${ano + 1}-01-01` : `${ano}-${String(mes + 1).padStart(2, "0")}-01`;
  return { inicio, fimExclusivo };
}

const DIAS_SEMANA = ["Dom","Seg","Ter","Qua","Qui","Sex","Sáb"];
function diaSemanaLabel(dataISO) {
  return DIAS_SEMANA[new Date(dataISO + "T00:00:00").getDay()];
}
function diaTemHorarioFixo(dataISO, feriado) {
  if (!dataISO) return true;
  const weekday = new Date(dataISO + "T00:00:00").getDay();
  return !feriado && weekday !== 0 && weekday !== 6;
}
const NOMES_MESES_EXTENSO = ["Janeiro","Fevereiro","Março","Abril","Maio","Junho","Julho","Agosto","Setembro","Outubro","Novembro","Dezembro"];
function mesRefExtenso(mesRef) {
  const [ano, mes] = mesRef.split("-").map(Number);
  return `${NOMES_MESES_EXTENSO[mes - 1]} de ${ano}`;
}

// =========================================================
// CAMADA SUPABASE (REST direto via fetch, sem o SDK supabase-js)
// =========================================================
async function sbRequest(path, session, { method = "GET", body, extraHeaders = {} } = {}) {
  const res = await fetch(`${SUPABASE_URL}/rest/v1/${path}`, {
    method,
    headers: {
      apikey: SUPABASE_ANON_KEY,
      Authorization: `Bearer ${session?.access_token || SUPABASE_ANON_KEY}`,
      "Content-Type": "application/json",
      Prefer: method === "GET" ? undefined : "return=representation",
      ...extraHeaders,
    },
    body: body ? JSON.stringify(body) : undefined,
  });
  if (!res.ok) {
    const errText = await res.text();
    throw new Error(`Supabase (${path}) ${res.status}: ${errText}`);
  }
  if (res.status === 204) return null;
  const text = await res.text();
  return text ? JSON.parse(text) : null;
}

async function sbLogin(email, password) {
  const res = await fetch(`${SUPABASE_URL}/auth/v1/token?grant_type=password`, {
    method: "POST",
    headers: { apikey: SUPABASE_ANON_KEY, "Content-Type": "application/json" },
    body: JSON.stringify({ email, password }),
  });
  const data = await res.json();
  if (!res.ok) throw new Error(data.error_description || data.msg || "Login inválido");
  return data;
}

// Cria um novo usuário direto do app (sem precisar do painel do Supabase).
// Usa o endpoint público de cadastro — NÃO afeta a sessão de quem está
// logado (o retorno é da conta nova, que simplesmente ignoramos).
async function sbSignup(email, password) {
  const res = await fetch(`${SUPABASE_URL}/auth/v1/signup`, {
    method: "POST",
    headers: { apikey: SUPABASE_ANON_KEY, "Content-Type": "application/json" },
    body: JSON.stringify({ email, password }),
  });
  const data = await res.json();
  if (!res.ok) throw new Error(data.error_description || data.msg || "Não foi possível criar o usuário.");
  return data;
}

async function sbUploadFoto(file, path, session) {
  const res = await fetch(`${SUPABASE_URL}/storage/v1/object/${FOTOS_BUCKET}/${path}`, {
    method: "POST",
    headers: {
      apikey: SUPABASE_ANON_KEY,
      Authorization: `Bearer ${session?.access_token}`,
      "Content-Type": file.type || "application/octet-stream",
      "x-upsert": "true",
    },
    body: file,
  });
  if (!res.ok) throw new Error("Falha ao enviar a foto para o Storage.");
  return `${SUPABASE_URL}/storage/v1/object/public/${FOTOS_BUCKET}/${path}`;
}

